    match env::var("XDG_CONFIG_HOME") {
        Ok(xdg) => {
            // Use xdg even if empty (will result in relative path "eureka/config.json")
            Ok(Path::new(&xdg).join("eureka/config.json"))
        }
        Err(_) => {
            match env::var("HOME") {
                Ok(home) => {
