                    }
                }
                Err(_) => {
                    Err("No such file or directory (os error 2)".to_string())
                }
            }
        }
    }
}

fn load_config() -> Result<Config, String> {
    let path = config_path()?;
    let content = fs::read_to_string(&path).map_err(|e| e.to_string())?;
    let cfg: Config = serde_json::from_str(&content).map_err(|e| e.to_string())?;
    Ok(cfg)
}

fn prompt_line(prompt_prefix: &str) -> Option<String> {
    // prompt_prefix already includes colors and prompt text up to "> "?
    // This function prints prompt_prefix and reads a line, returns trimmed? Actually return raw line? We'll handle trimming outside.
    // Returns None on EOF? No, read_line returns 0 on EOF, we treat as empty string (to loop).
    // For our loops, we need to distinguish? Original loops on EOF as empty, so just return empty string on EOF.
    print!("{}", prompt_prefix);
    io::stdout().flush().ok()?;
    let stdin = io::stdin();
    let mut line = String::new();
    let mut lock = stdin.lock();
    match lock.read_line(&mut line) {
        Ok(0) => Some(String::new()), // EOF -> empty
        Ok(_) => Some(line),
        Err(_) => Some(String::new()),
    }
}

fn run_setup() {
    // Banner
    // Exact bytes: "\x1b[0m\x1b[33m...banner...\n        \n\x1b[0m"
    // Then prompt loop
    let banner = "\x1b[0m\x1b[33m############################################################\n####                  First Time Setup                  ####\n############################################################\n\nThis tool requires you to have a repository with a README.md\nin the root folder. The markdown file is where your ideas\nwill be stored.\n\nOnce first time setup has completed, simply run Eureka again\nto begin writing down ideas.\n        \n\x1b[0m";
    print!("{}", banner);
    // Note: banner ends with \x1b[0m, then prompt prefix starts with \x1b[0m...
    // Flush?
    io::stdout().flush().ok();

    let prompt_prefix = "\x1b[0m\x1b[1m\x1b[32mAbsolute path to your idea repo\n\x1b[0m> ";
    loop {
        // print prompt and read
        print!("{}", prompt_prefix);
        io::stdout().flush().ok();
        let stdin = io::stdin();
        let mut line = String::new();
        let n = {
            let mut lock = stdin.lock();
            match lock.read_line(&mut line) {
                Ok(n) => n,
                Err(_) => 0,
            }
        };
        // n==0 means EOF, line is empty -> treat as empty (will loop)
        // Trim
        let trimmed = line.trim().to_string();
        if trimmed.is_empty() {
            continue;
        }
        // Check absolute
        let p = Path::new(&trimmed);
        if !p.is_absolute() {
            continue;
        }
        // Try to write config
        let cfg_path = match config_path() {
            Ok(p) => p,
            Err(e) => {
                log_error(&e);
                return;
            }
        };
        // Ensure parent dirs
        if let Some(parent) = cfg_path.parent() {
            if let Err(e) = fs::create_dir_all(parent) {
                log_error(&e.to_string());
                return;
            }
        }
        let json = format!("{{\"repo\":\"{}\"}}", trimmed);
        // Use write (no newline)
        match fs::write(&cfg_path, json) {
            Ok(_) => {
                println!("First time setup complete. Happy ideation!");
                return;
            }
            Err(e) => {
                log_error(&e.to_string());
                return;
            }
        }
    }
}

fn find_executable(name: &str) -> Option<PathBuf> {
    // Search PATH for executable
    if let Ok(path_var) = env::var("PATH") {
        for dir in path_var.split(':') {
            if dir.is_empty() {
                continue;
            }
            let candidate = Path::new(dir).join(name);
            // Check exists and is file and executable?
            if let Ok(md) = fs::metadata(&candidate) {
                if md.is_file() {
                    // Check executable bit on unix
                    #[cfg(unix)]
                    {
                        use std::os::unix::fs::PermissionsExt;
                        let mode = md.permissions().mode();
                        if mode & 0o111 != 0 {
                            return Some(candidate);
                        } else {
                            // Not executable, continue? Original `which` would skip non-executable?
                            // For our purposes, if file exists but not executable, then Command::new would give Permission denied,
                            // but `which` would skip and continue searching? Let's continue searching.
                            continue;
                        }
                    }
                    #[cfg(not(unix))]
                    {
                        return Some(candidate);
                    }
                }
            }
        }
    }
    None
}

fn run_clear_config() {
    let path = match config_path() {
        Ok(p) => p,
        Err(e) => {
            log_error(&e);
            return;
        }
    };
    match fs::remove_file(&path) {
        Ok(_) => {},
        Err(e) => {
            log_error(&e.to_string());
        }
    }
}

fn run_view(cfg: Config) {
    let readme = cfg.repo.join("README.md");
    // Check readme exists? Try to ensure file exists, if not log io error.
    // Original logs "No such file..." for missing readme, even before pager.
    // How to check? Use metadata? If metadata fails, log io error and return.
    // If metadata succeeds but is directory, then later pager? Actually for directory, view would... what does original do for README as dir with view?
    // Let's test later, but for now: if metadata fails, log and return.
    // If metadata succeeds but is dir, what? Pager with dir as arg would fail? `cat dir` gives "Is a directory"? But original for idea flow with dir readme gave git error, not io. For view with dir readme, what?
    // For view, we should just try to run pager; if readme is dir, `cat dir` would output "Is a directory" to stderr (from cat), not via log. But original might check and log "Is a directory"? Let's just check metadata: if is_dir, then what? For idea flow, dir readme gives git error (from add_path), not io. For view, dir readme would... let's just run pager and let pager handle? But to match "No such file..." for missing, we need to check existence first.
    // Simplest: try fs::metadata, if Err log and return, else run pager.
    // If metadata is dir, still run pager? Then pager (cat) would fail with its own message, not log format. But would original log or pager message? Let's test view with dir readme later.
    // For now, implement: if metadata Err, log and return, else run pager.
    match fs::metadata(&readme) {
        Ok(_) => {},
        Err(e) => {
            log_error(&e.to_string());
            return;
        }
    }
    // Get pager
    let pager_bin: String = match env::var("PAGER") {
        Ok(val) => val,
        Err(_) => {
            // fallback to less
            match find_executable("less") {
                Some(p) => p.to_string_lossy().to_string(),
                None => {
                    log_error("cannot find binary path");
                    return;
                }
            }
        }
    };
    // If pager_bin is empty? Then Command::new("") will fail with NotFound -> log io error. Good.
    // Run pager with readme as arg, inherit stdio
    match std::process::Command::new(&pager_bin).arg(&readme).status() {
        Ok(_) => {},
        Err(e) => {
            log_error(&e.to_string());
        }
    }
}

fn checkout_main(repo: &Repository) -> Result<(), String> {
    // If main exists, checkout it; else create from HEAD and checkout
    match repo.find_branch("main", BranchType::Local) {
        Ok(_) => {
            repo.set_head("refs/heads/main").map_err(|e| e.to_string())?;
            let mut co = git2::build::CheckoutBuilder::new();
            // default safe checkout (no force)
            repo.checkout_head(Some(&mut co)).map_err(|e| e.to_string())?;
            Ok(())
        }
        Err(e) => {
            if e.code() == ErrorCode::NotFound {
                // create from HEAD
                let head = repo.head().map_err(|e| e.to_string())?;
                let commit = head.peel_to_commit().map_err(|e| e.to_string())?;
                repo.branch("main", &commit, false).map_err(|e| e.to_string())?;
                repo.set_head("refs/heads/main").map_err(|e| e.to_string())?;
                let mut co = git2::build::CheckoutBuilder::new();
                repo.checkout_head(Some(&mut co)).map_err(|e| e.to_string())?;
                Ok(())
            } else {
                Err(e.to_string())
            }
        }
    }
}

fn do_commit(repo: &Repository, summary: &str) -> Result<(), String> {
    let mut index = repo.index().map_err(|e| e.to_string())?;
    index.add_path(Path::new("README.md")).map_err(|e| e.to_string())?;
    index.write().map_err(|e| e.to_string())?;
    let tree_id = index.write_tree().map_err(|e| e.to_string())?;
    let tree = repo.find_tree(tree_id).map_err(|e| e.to_string())?;
    let parent = repo.head().map_err(|e| e.to_string())?.peel_to_commit().map_err(|e| e.to_string())?;
    let sig = repo.signature().map_err(|e| e.to_string())?;
    repo.commit(Some("HEAD"), &sig, &sig, summary, &tree, &[&parent]).map_err(|e| e.to_string())?;
    Ok(())
}

fn do_push(repo: &Repository) -> Result<(), String> {
    let mut remote = repo.find_remote("origin").map_err(|e| e.to_string())?;
    // Push main to main
    remote.push(&["refs/heads/main:refs/heads/main"], None).map_err(|e| e.to_string())?;
    Ok(())
}

fn run_idea(cfg: Config) {
    // Prompt for summary
    let prompt_prefix = "\x1b[0m\x1b[1m\x1b[32m>> Idea summary\n\x1b[0m> ";
    let summary: String = loop {
        print!("{}", prompt_prefix);
        io::stdout().flush().ok();
        let stdin = io::stdin();
        let mut line = String::new();
        let _n = {
            let mut lock = stdin.lock();
            match lock.read_line(&mut line) {
                Ok(n) => n,
                Err(_) => 0,
            }
        };
        let trimmed = line.trim().to_string();
        if trimmed.is_empty() {
            continue;
        } else {
            break trimmed;
        }
    };

    // Resolve editor (first_err)
    let mut first_err: Option<String> = None;
    let editor_bin_opt: Option<String> = match env::var("EDITOR") {
        Ok(val) => Some(val),
        Err(_) => {
            match find_executable("vi") {
                Some(p) => Some(p.to_string_lossy().to_string()),
                None => {
                    first_err = Some("cannot find binary path".to_string());
                    None
                }
            }
        }
    };

    // Open repo
    let repo = match Repository::open(&cfg.repo) {
        Ok(r) => r,
        Err(e) => {
            if let Some(fe) = first_err {
                log_error(&fe);
            } else {
                log_error(&e.to_string());
            }
            return;
        }
    };

    println!("Adding and committing your new idea to main..");

    // Checkout main
    if let Err(e) = checkout_main(&repo) {
        if let Some(fe) = first_err {
            log_error(&fe);
        } else {
            log_error(&e);
        }
        return;
    }

    // Check README exists (metadata)
    let readme = cfg.repo.join("README.md");
    if let Err(e) = fs::metadata(&readme) {
        if let Some(fe) = first_err {
            log_error(&fe);
        } else {
            log_error(&e.to_string());
        }
        return;
    }

    // Execute editor if we have binary
    let mut exec_err: Option<String> = None;
    if let Some(bin) = editor_bin_opt {
        // bin could be empty string -> Command::new("") will fail with NotFound
        match std::process::Command::new(&bin).arg(&readme).status() {
            Ok(_) => {},
            Err(e) => {
                exec_err = Some(e.to_string());
            }
        }
        if first_err.is_none() {
            first_err = exec_err;
        }
        // if first_err already Some (fallback failed), keep it (exec not executed? Actually if editor_bin_opt is None, we skip exec, first_err already Some)
        // If editor_bin_opt is Some but exec failed, first_err becomes exec_err (if previously None)
    } else {
        // No editor binary (fallback failed), first_err already Some, skip exec
    }

    // Commit
    if let Err(e) = do_commit(&repo, &summary) {
        if let Some(fe) = first_err {
            log_error(&fe);
        } else {
            log_error(&e);
        }
        return;
    }

    println!("Added and committed!");
    println!("Pushing your new idea..");

    match do_push(&repo) {
        Ok(_) => {
            println!("Pushed!");
            if let Some(fe) = first_err {
                log_error(&fe);
            }
        }
        Err(e) => {
            if let Some(fe) = first_err {
                log_error(&fe);
            } else {
                log_error(&e);
            }
        }
    }
}

fn main() {
    let cli = Cli::parse();
    if cli.clear_config {
        run_clear_config();
        return;
    }
    if cli.view {
        match load_config() {
            Ok(cfg) => run_view(cfg),
            Err(e) => log_error(&e),
        }
        return;
    }
    // Normal flow: try load config, if fails trigger setup, else idea
    match load_config() {
        Ok(cfg) => run_idea(cfg),
        Err(_) => run_setup(),
    }
}
